steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        projects(filter: { name: { contains: \"Checkout Redesign\" } }) {
          nodes {
            id
            name
            targetDate
            description
            states {
              nodes {
                id
                name
                type
                targetDate
              }
            }
          }
        }
      }
    "
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d @- <<'EOF'
{
  "query": "query {
    proj1: project(id: \"p-1\") { id name lead { id name } milestones { nodes { id name targetDate } } }
    proj2: project(id: \"p-2\") { id name lead { id name } milestones { nodes { id name targetDate } } }
  }"
}
EOF

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d @- <<'EOF'
{
  "query": "query {
    proj1: project(id: \"p-1\") { id name lead { id name } }
    proj2: project(id: \"p-2\") { id name lead { id name } }
  }"
}
EOF

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d @- <<'EOF'
{
  "query": "query {
    s1: searchProjects(term: \"Checkout Redesign\") { nodes { id name lead { id name } } }
    m1: projectMilestones(filter: { projectId: { eq: \"p-1\" } }) { nodes { id name targetDate projectId } }
    m2: projectMilestones(filter: { projectId: { eq: \"p-2\" } }) { nodes { id name targetDate projectId } }
  }"
}
EOF

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d @- <<'EOF'
{
  "query": "query {
    f: __type(name: \"ProjectMilestoneFilter\") { inputFields { name type { name kind ofType { name } } } }
    m: __type(name: \"ProjectMilestone\") { fields { name } }
  }"
}
EOF
